            if f.endswith(".gz"):
                with gzip.open(f, 'rt', errors='ignore') as fh:
                    data=fh.read()
            elif f.endswith(".bz2"):
                with bz2.open(f, 'rt', errors='ignore') as fh:
                    data=fh.read()
            else:
                with open(f, 'r', errors='ignore') as fh:
                    data=fh.read()
            h=hashlib.md5(data.encode()).hexdigest()
            if h in seen:
                print(f"skip {f} dup {seen[h]} hash {h[:6]}")
                continue
            seen[h]=f
            deduped.append(f)
        except Exception as e:
            print(e)
            deduped.append(f)
    return deduped

